SELECT \"nct\", \"author\", \"year\", \"pubmed_id\", \"trial_phase\", \"cancer_type\", \"treatment_regimen\", \"control_regimen\", \"type_of_combination\", \"class_of_ici\" FROM public.\"clinical_trials\" WHERE \"trial_phase\" = 'Phase 3' AND \"cancer_type\" = 'Melanoma' AND \"class_of_ici\" = 'CTLA4' AND \"type_of_combination\" IS NOT NULL;